"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource"
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"
import { ScrollArea } from "@/components/ui/scroll-area"

import { createPdfPageLayout, getPdfPageLayout } from "./pdf-viewer-layout"
import { PdfPage } from "./pdf-viewer-page"
import { usePdfPageSizes } from "./pdf-viewer-page-sizes"
import { PdfViewerRail } from "./pdf-viewer-rail"
import {
  clearDocumentResource,
  readDocumentResource,
  readPageResource,
  releaseDocumentResource,
  retainDocumentResource,
} from "./pdf-viewer-resource"
import { useMeasuredElementWidth, usePdfScale } from "./pdf-viewer-scale"
import { usePdfScroll } from "./pdf-viewer-scroll"
import { PageSkeleton, PdfViewerFallback } from "./pdf-viewer-states"
import { PdfViewerToolbar } from "./pdf-viewer-toolbar"
import type {
  PageOverlayProps,
  PdfPageSize,
  PdfViewerHandle,
  PdfViewerSlots,
} from "./pdf-viewer-types"
import { usePdfPageVirtualization } from "./pdf-viewer-virtualization"
import { ViewerErrorBoundary } from "./viewer-error"

export { getDocumentResource, getPageResource } from "./pdf-viewer-resource"
export type {
  PageOverlayProps,
  PdfPageScrollTarget,
  PdfViewerHandle,
  PdfViewerSlots,
} from "./pdf-viewer-types"

export type PdfDocumentSource = UrlViewerSource | BlobViewerSource

function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

export interface PdfHighlightProps extends React.ComponentProps<"div"> {
  /** Normalized box, each field a percentage [0, 100] of the page. */
  area: { left: number; top: number; width: number; height: number }
}

export function PdfHighlight({
  area,
  className,
  style,
  ...props
}: PdfHighlightProps) {
  return (
    <div
      data-slot="pdf-highlight"
      className={cn(
        "pointer-events-none absolute z-10 rounded-[2px] border border-primary/70 bg-primary/12 shadow-[0_4px_16px_rgb(0_0_0_/_8%)]",
        className
      )}
      style={{
        left: `${area.left}%`,
        top: `${area.top}%`,
        width: `${area.width}%`,
        height: `${area.height}%`,
        ...style,
      }}
      {...props}
    />
  )
}

export interface PdfViewerProps {
  /** Canonical PDF source. URL sources preserve PDF.js range-loading behavior. */
  source: PdfDocumentSource
  className?: string
  /** Controlled rendered scale; when omitted the viewer fits page width until manually zoomed. */
  scale?: number
  /** Initial uncontrolled scale. Leave unset for fit-to-width. */
  defaultScale?: number
  /** Called when toolbar controls request a scale change. `null` means fit width. */
  onScaleChange?: (scale: number | null) => void
  toolbar?: boolean
  /** Render absolutely-positioned overlays (e.g. bbox citations) on each page. */
  renderPageOverlay?: (props: PageOverlayProps) => React.ReactNode
  /** Fired with the 1-based page nearest the top of the viewport as you scroll. */
  onVisiblePageChange?: (page: number) => void
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /**
   * Chrome mounted around the document. `top`/`bottom` are document-column
   * strips, `left`/`right` are rails, and `overlay` floats over the scroller.
   */
  slots?: PdfViewerSlots
  /** Show the toolbar button that collapses/expands rails. */
  railToggle?: boolean
  /** Initial open state of the rails. */
  defaultRailsOpen?: boolean
}

export type PdfResourceViewerProps = Omit<PdfViewerProps, "source"> & {
  resource: ViewerResource
}

export const PdfViewer = React.forwardRef<PdfViewerHandle, PdfViewerProps>(
  function PdfViewer(props, ref) {
    const { source, ...resourceProps } = props
    const resource = React.useMemo(() => createViewerResource(source), [source])
    return (
      <PdfResourceViewer {...resourceProps} ref={ref} resource={resource} />
    )
  }
)

export const PdfResourceViewer = React.forwardRef<
  PdfViewerHandle,
  PdfResourceViewerProps
>(function PdfResourceViewer(props, ref) {
  const resource = props.resource
  const isClient = useIsClient()
  const hasRail = Boolean(props.slots?.left ?? props.slots?.right)
  const showRailToggle = Boolean(hasRail && (props.railToggle ?? true))

  if (!isClient) {
    return (
      <PdfViewerFallback
        className={props.className}
        bare={props.bare}
        toolbar={props.toolbar}
        showRailToggle={showRailToggle}
      />
    )
  }

  return (
    <ViewerErrorBoundary
      className={props.className}
      download={resource.originalDownload}
      format="pdf"
      onRetry={() => clearDocumentResource(resource.content)}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
    >
      <React.Suspense
        fallback={
          <PdfViewerFallback
            className={props.className}
            bare={props.bare}
            toolbar={props.toolbar}
            showRailToggle={showRailToggle}
          />
        }
      >
        <PdfViewerInner {...props} forwardedRef={ref} resource={resource} />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
})

function PdfViewerInner({
  resource,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  toolbar = true,
  renderPageOverlay,
  onVisiblePageChange,
  onScrollProgressChange,
  bare = false,
  slots,
  railToggle,
  defaultRailsOpen,
  forwardedRef,
}: Omit<PdfViewerProps, "source"> & {
  forwardedRef?: React.ForwardedRef<PdfViewerHandle>
  resource: ViewerResource
}) {
  const topSlot = slots?.top
  const bottomSlot = slots?.bottom
  const leftRailSlot = slots?.left
  const rightRailSlot = slots?.right
  const overlaySlot = slots?.overlay
  const showRailToggle = Boolean(
    (leftRailSlot || rightRailSlot) && (railToggle ?? true)
  )
  const [railsOpen, setRailsOpen] = React.useState(defaultRailsOpen ?? true)

  const content = resource.content
  const document = readDocumentResource(content)
  React.useEffect(() => {
    retainDocumentResource(content, document)
    return () => releaseDocumentResource(content, document)
  }, [content, document])

  const firstPage = readPageResource(document, 1)
  const firstPageSize = React.useMemo<PdfPageSize>(() => {
    const viewport = firstPage.getViewport({ scale: 1 })
    return { width: viewport.width, height: viewport.height }
  }, [firstPage])

  const { ref: containerRef, width: containerWidth } = useMeasuredElementWidth()
  const [rotationState, setRotationState] = React.useState<{
    document: typeof document
    value: number
  }>(() => ({ document, value: 0 }))
  const rotation = Object.is(rotationState.document, document)
    ? rotationState.value
    : 0
  const fitPageWidth =
    rotation % 180 === 0 ? firstPageSize.width : firstPageSize.height
  const { resolvedScale, zoomIn, zoomOut, fitWidth } = usePdfScale({
    controlledScale,
    defaultScale,
    onScaleChange,
    containerWidth,
    pageWidth: fitPageWidth,
    resetKey: document,
  })

  const { pageSizeByNumber, setPageSize } = usePdfPageSizes(document)
  const pageLayout = React.useMemo(
    () =>
      createPdfPageLayout({
        pageCount: document.numPages,
        defaultPageSize: firstPageSize,
        pageSizeByNumber,
        scale: resolvedScale,
        rotation,
      }),
    [
      document.numPages,
      firstPageSize,
      pageSizeByNumber,
      resolvedScale,
      rotation,
    ]
  )
  const {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPageTarget,
    getViewportElement,
  } = usePdfScroll({
    pageCount: document.numPages,
    layout: pageLayout,
    resetKey: document,
    onVisiblePageChange,
    onScrollProgressChange,
  })
  const { visiblePageNumbers, measureVisiblePages } = usePdfPageVirtualization({
    layout: pageLayout,
    resetKey: document,
    viewportElement,
  })

  React.useEffect(() => {
    measureScroll()
  }, [
    document.numPages,
    measureScroll,
    rotation,
    resolvedScale,
    viewportElement,
  ])

  const handleViewportScroll = React.useCallback(() => {
    handleScroll()
    measureVisiblePages()
  }, [handleScroll, measureVisiblePages])

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToPageTarget,
      getViewportElement,
    }),
    [getViewportElement, scrollToPageTarget]
  )

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="pdf-viewer"
    >
      {toolbar ? (
        <PdfViewerToolbar
          currentPage={currentPage}
          pageCount={document.numPages}
          scale={resolvedScale}
          downloadAction={resource.originalDownload}
          showRailToggle={showRailToggle}
          railsOpen={railsOpen}
          onToggleRails={() => setRailsOpen((open) => !open)}
          onZoomOut={zoomOut}
          onZoomIn={zoomIn}
          onFitWidth={fitWidth}
          onRotate={() =>
            setRotationState((state) => ({
              document,
              value:
                ((Object.is(state.document, document) ? state.value : 0) + 90) %
                360,
            }))
          }
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {leftRailSlot ? (
          <PdfViewerRail side="left" open={railsOpen} animate={showRailToggle}>
            {leftRailSlot}
          </PdfViewerRail>
        ) : null}
        <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
          {topSlot ? <div data-slot="pdf-viewer-top">{topSlot}</div> : null}
          <div className="relative flex min-h-0 flex-1 flex-col">
            <ScrollArea
              className="min-h-0 flex-1"
              viewportRef={setViewportElement}
              viewportProps={{ onScroll: handleViewportScroll }}
            >
              <div
                ref={containerRef}
                className="relative mx-auto"
                style={{
                  height: pageLayout.totalHeight,
                  minWidth: pageLayout.maxPageWidth,
                }}
              >
                {visiblePageNumbers.map((pageNumber) => {
                  const page = getPdfPageLayout(pageLayout, pageNumber)
                  if (!page) return null

                  return (
                    <div
                      key={pageNumber}
                      data-slot="pdf-page-slot"
                      data-page-number={pageNumber}
                      className="absolute left-1/2 flex -translate-x-1/2 items-center justify-center"
                      style={{
                        top: page.offsetTop,
                        width: page.width,
                        minHeight: page.height,
                      }}
                    >
                      <React.Suspense fallback={<PageSkeleton />}>
                        <PdfPage
                          document={document}
                          pageNumber={pageNumber}
                          scale={resolvedScale}
                          rotation={rotation}
                          renderOverlay={renderPageOverlay}
                          onSize={setPageSize}
                        />
                      </React.Suspense>
                    </div>
                  )
                })}
              </div>
            </ScrollArea>
            {overlaySlot ? (
              <div
                data-slot="pdf-viewer-overlay"
                className="pointer-events-none absolute inset-0 z-10 [&>*]:pointer-events-auto"
              >
                {overlaySlot}
              </div>
            ) : null}
          </div>
          {bottomSlot ? (
            <div data-slot="pdf-viewer-bottom">{bottomSlot}</div>
          ) : null}
        </div>
        {rightRailSlot ? (
          <PdfViewerRail side="right" open={railsOpen} animate={showRailToggle}>
            {rightRailSlot}
          </PdfViewerRail>
        ) : null}
      </div>
    </div>
  )
}

import type * as React from "react"

export interface PageOverlayProps {
  pageNumber: number
  /** Rendered page size in CSS pixels (post-scale, post-rotation). */
  width: number
  height: number
  scale: number
  rotation: number
}

export type PdfPageScrollTarget = {
  top: number
}

export interface PdfViewerHandle {
  scrollToPageTarget: (
    pageNumber: number,
    target: PdfPageScrollTarget,
    options?: ScrollToOptions
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export interface PdfViewerSlots {
  /** Full-width strip directly below the toolbar (e.g. a legend). */
  top?: React.ReactNode
  /** Full-width strip at the bottom of the document column (e.g. a waterfall). */
  bottom?: React.ReactNode
  /** Collapsible rail to the left of the pages (e.g. a vertical page ribbon). */
  left?: React.ReactNode
  /** Collapsible rail to the right of the pages. */
  right?: React.ReactNode
  /** Absolutely-positioned layer over the scrolling pages (e.g. a floating legend). */
  overlay?: React.ReactNode
}

export type PdfPageSize = {
  width: number
  height: number
}

import type * as Pdfjs from "pdfjs-dist"
import type { PDFDocumentProxy, PDFPageProxy } from "pdfjs-dist"

import {
  isResourceError,
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors"
import type {
  ViewerContentBytes,
  ViewerContentDirectUrl,
  ViewerContentIdentity,
} from "@/lib/viewer-resource"

const PDF_CACHE_MAX = 6

type PdfDocumentContent = ViewerContentIdentity &
  ViewerContentDirectUrl &
  ViewerContentBytes

type DocumentCacheEntry = {
  loadKey: string
  promise: Promise<PDFDocumentProxy>
  consumers: number
  lastUsedAt: number
  retainRejected: boolean
  status: "pending" | "resolved" | "rejected"
  document?: PDFDocumentProxy
  error?: unknown
}

type PageCacheEntry = {
  promise: Promise<PDFPageProxy>
  retainRejected: boolean
  status: "pending" | "resolved" | "rejected"
  page?: PDFPageProxy
  error?: unknown
}

type PdfResourceOptions = {
  retainRejected?: boolean
}

let pdfjsPromise: Promise<typeof Pdfjs> | null = null
const documentCache = new Map<string, DocumentCacheEntry>()
const pageCache = new WeakMap<PDFDocumentProxy, Map<number, PageCacheEntry>>()
const detachedDocumentEntries = new Set<DocumentCacheEntry>()
let pruneTimer = 0

function loadPdfjs() {
  if (!pdfjsPromise) {
    pdfjsPromise = import("pdfjs-dist").then((pdfjs) => {
      if (!pdfjs.GlobalWorkerOptions.workerSrc) {
        pdfjs.GlobalWorkerOptions.workerSrc = new URL(
          "pdfjs-dist/build/pdf.worker.min.mjs",
          import.meta.url
        ).toString()
      }
      return pdfjs
    })
  }
  return pdfjsPromise
}

function scheduleDocumentPrune() {
  if (typeof window === "undefined" || pruneTimer) return
  pruneTimer = window.setTimeout(() => {
    pruneTimer = 0
    pruneDocumentCache()
  }, 0)
}

function pruneDocumentCache() {
  while (documentCache.size > PDF_CACHE_MAX) {
    let evictKey: string | null = null
    let evictEntry: DocumentCacheEntry | null = null
    for (const [key, documentEntry] of documentCache) {
      if (documentEntry.consumers > 0 || documentEntry.status === "pending") {
        continue
      }
      if (!evictEntry || documentEntry.lastUsedAt < evictEntry.lastUsedAt) {
        evictKey = key
        evictEntry = documentEntry
      }
    }
    if (!evictKey || !evictEntry) return
    documentCache.delete(evictKey)
    if (evictEntry.status === "resolved") {
      if (!hasDetachedDocument(evictEntry.document)) {
        destroyPdfDocument(evictEntry.document)
      }
    }
  }
}

export function getDocumentResource(
  content: PdfDocumentContent,
  options: PdfResourceOptions = {}
): Promise<PDFDocumentProxy> {
  return getDocumentCacheEntry(content, options).promise
}

export function readDocumentResource(
  content: PdfDocumentContent
): PDFDocumentProxy {
  const documentEntry = getDocumentCacheEntry(content, {
    retainRejected: true,
  })
  documentEntry.lastUsedAt = Date.now()
  if (documentEntry.status === "pending") throw documentEntry.promise
  if (documentEntry.status === "rejected") throw documentEntry.error
  return documentEntry.document!
}

function getDocumentCacheEntry(
  content: PdfDocumentContent,
  options: PdfResourceOptions
) {
  const loadKey = content.key
  const cachedDocumentEntry = documentCache.get(loadKey)
  if (cachedDocumentEntry) {
    if (options.retainRejected) {
      cachedDocumentEntry.retainRejected = true
    }
    if (cachedDocumentEntry.status === "rejected" && !options.retainRejected) {
      documentCache.delete(loadKey)
    } else {
      cachedDocumentEntry.lastUsedAt = Date.now()
      return cachedDocumentEntry
    }
  }

  const documentEntry: DocumentCacheEntry = {
    loadKey,
    promise: Promise.resolve(null as never),
    consumers: 0,
    lastUsedAt: Date.now(),
    retainRejected: Boolean(options.retainRejected),
    status: "pending",
  }
  documentEntry.promise = loadPdfjs()
    .then((pdfjs) => getPdfDocument(content, pdfjs))
    .then(
      (document) => {
        documentEntry.status = "resolved"
        documentEntry.document = document
        if (documentCache.get(loadKey) !== documentEntry) {
          destroyPdfDocument(document)
        } else {
          scheduleDocumentPrune()
        }
        return document
      },
      (error) => {
        documentEntry.status = "rejected"
        documentEntry.error = error
        if (
          !documentEntry.retainRejected &&
          documentCache.get(loadKey) === documentEntry
        ) {
          documentCache.delete(loadKey)
        }
        throw error
      }
    )

  documentCache.set(loadKey, documentEntry)
  scheduleDocumentPrune()
  return documentEntry
}

export function clearDocumentResource(content: ViewerContentIdentity) {
  const documentEntry = documentCache.get(content.key)
  if (!documentEntry) return
  documentCache.delete(content.key)
  if (documentEntry.status === "resolved") {
    clearPageCache(documentEntry.document)
    if (documentEntry.consumers > 0) {
      detachedDocumentEntries.add(documentEntry)
    } else if (hasDetachedDocument(documentEntry.document)) {
      return
    } else {
      destroyPdfDocument(documentEntry.document)
    }
  }
}

export function retainDocumentResource(
  content: ViewerContentIdentity,
  document: PDFDocumentProxy
) {
  const documentEntry = documentCache.get(content.key)
  if (!documentEntry || documentEntry.document !== document) return
  documentEntry.consumers += 1
  documentEntry.lastUsedAt = Date.now()
}

export function releaseDocumentResource(
  content: ViewerContentIdentity,
  document: PDFDocumentProxy
) {
  const documentEntry =
    findDetachedDocumentEntry(content, document) ??
    findAttachedDocumentEntry(content, document)
  if (!documentEntry || documentEntry.document !== document) return
  documentEntry.consumers = Math.max(0, documentEntry.consumers - 1)
  documentEntry.lastUsedAt = Date.now()
  if (detachedDocumentEntries.has(documentEntry)) {
    if (documentEntry.consumers === 0) {
      detachedDocumentEntries.delete(documentEntry)
      if (!hasAttachedDocument(documentEntry.document)) {
        destroyPdfDocument(documentEntry.document)
      }
    }
    return
  }
  scheduleDocumentPrune()
}

export function __resetPdfDocumentCacheForTests() {
  pdfjsPromise = null
  if (pruneTimer && typeof window !== "undefined") {
    window.clearTimeout(pruneTimer)
    pruneTimer = 0
  }
  const destroyedDocuments = new Set<PDFDocumentProxy>()
  for (const documentEntry of documentCache.values()) {
    if (documentEntry.status === "resolved") {
      destroyPdfDocumentOnce(documentEntry.document, destroyedDocuments)
    }
  }
  for (const documentEntry of detachedDocumentEntries) {
    if (documentEntry.status === "resolved") {
      destroyPdfDocumentOnce(documentEntry.document, destroyedDocuments)
    }
  }
  documentCache.clear()
  detachedDocumentEntries.clear()
}

function findAttachedDocumentEntry(
  content: ViewerContentIdentity,
  document: PDFDocumentProxy
) {
  const documentEntry = documentCache.get(content.key)
  return documentEntry?.document === document ? documentEntry : undefined
}

function findDetachedDocumentEntry(
  content: ViewerContentIdentity,
  document: PDFDocumentProxy
) {
  for (const documentEntry of detachedDocumentEntries) {
    if (
      documentEntry.loadKey === content.key &&
      documentEntry.document === document
    ) {
      return documentEntry
    }
  }
  return undefined
}

function hasAttachedDocument(document: PDFDocumentProxy | undefined) {
  for (const documentEntry of documentCache.values()) {
    if (documentEntry.document === document) return true
  }
  return false
}

function hasDetachedDocument(document: PDFDocumentProxy | undefined) {
  for (const documentEntry of detachedDocumentEntries) {
    if (documentEntry.document === document) return true
  }
  return false
}

export function getPageResource(
  document: PDFDocumentProxy,
  pageNumber: number,
  options: PdfResourceOptions = {}
) {
  return getPageCacheEntry(document, pageNumber, options).promise
}

export function readPageResource(
  document: PDFDocumentProxy,
  pageNumber: number
): PDFPageProxy {
  const pageEntry = getPageCacheEntry(document, pageNumber, {
    retainRejected: true,
  })
  if (pageEntry.status === "pending") throw pageEntry.promise
  if (pageEntry.status === "rejected") throw pageEntry.error
  return pageEntry.page!
}

function getPageCacheEntry(
  document: PDFDocumentProxy,
  pageNumber: number,
  options: PdfResourceOptions
) {
  let pages = pageCache.get(document)
  if (!pages) {
    pages = new Map()
    pageCache.set(document, pages)
  }
  const cachedPageEntry = pages.get(pageNumber)
  if (cachedPageEntry) {
    if (options.retainRejected) {
      cachedPageEntry.retainRejected = true
    }
    if (cachedPageEntry.status === "rejected" && !options.retainRejected) {
      pages.delete(pageNumber)
    } else {
      return cachedPageEntry
    }
  }

  const pageEntry: PageCacheEntry = {
    promise: document.getPage(pageNumber),
    retainRejected: Boolean(options.retainRejected),
    status: "pending",
  }
  pages.set(pageNumber, pageEntry)
  pageEntry.promise.then(
    (page) => {
      pageEntry.status = "resolved"
      pageEntry.page = page
    },
    (error) => {
      pageEntry.status = "rejected"
      pageEntry.error = error
      if (!pageEntry.retainRejected && pages?.get(pageNumber) === pageEntry) {
        pages.delete(pageNumber)
      }
    }
  )
  return pageEntry
}

async function getPdfDocument(
  content: PdfDocumentContent,
  pdfjs: typeof Pdfjs
): Promise<PDFDocumentProxy> {
  try {
    if (content.directUrl) {
      return await pdfjs.getDocument(content.directUrl).promise
    }

    const buffer = await content.readBytes()
    return await pdfjs.getDocument({ data: new Uint8Array(buffer) }).promise
  } catch (error) {
    if (isResourceError(error)) throw error
    throw toPdfFormatError(error, {
      kind: "parse_failed",
      message: "Failed to parse PDF.",
    })
  }
}

function toPdfFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions
): ViewerFormatError {
  if (isViewerFormatError(error)) return error
  return new ViewerFormatError({
    format: "pdf",
    kind: options.kind,
    message: options.message,
    cause: error,
  })
}

function destroyPdfDocument(document: PDFDocumentProxy | undefined) {
  clearPageCache(document)
  void document?.destroy().catch(() => {})
}

function destroyPdfDocumentOnce(
  document: PDFDocumentProxy | undefined,
  destroyedDocuments: Set<PDFDocumentProxy>
) {
  if (!document || destroyedDocuments.has(document)) return
  destroyedDocuments.add(document)
  destroyPdfDocument(document)
}

function clearPageCache(document: PDFDocumentProxy | undefined) {
  if (document) pageCache.delete(document)
}

import * as React from "react"

export const MIN_PDF_SCALE = 0.25
export const MAX_PDF_SCALE = 5
export const PDF_ZOOM_STEP = 1.2
export const PDF_PAGE_HORIZONTAL_PADDING = 32

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function clampPdfScale(value: number) {
  return clamp(Number.isFinite(value) ? value : 1, MIN_PDF_SCALE, MAX_PDF_SCALE)
}

export function getPdfFitWidthScale(
  containerWidth: number | null,
  pageWidth: number
) {
  if (!containerWidth || !Number.isFinite(containerWidth) || pageWidth <= 0) {
    return 1
  }
  return clampPdfScale(
    (containerWidth - PDF_PAGE_HORIZONTAL_PADDING) / pageWidth
  )
}

export function useMeasuredElementWidth() {
  const [width, setWidth] = React.useState<number | null>(null)

  const ref = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    setWidth(element.clientWidth)
    if (typeof ResizeObserver === "undefined") return

    let frame = 0
    let latestWidth = element.clientWidth
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        latestWidth = (entry.target as HTMLElement).clientWidth
      }
      if (frame) return
      frame = requestAnimationFrame(() => {
        frame = 0
        setWidth(latestWidth)
      })
    })

    observer.observe(element)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [])

  return { ref, width }
}

export function usePdfScale({
  controlledScale,
  defaultScale,
  onScaleChange,
  containerWidth,
  pageWidth,
  resetKey,
}: {
  controlledScale?: number
  defaultScale?: number
  onScaleChange?: (scale: number | null) => void
  containerWidth: number | null
  pageWidth: number
  resetKey?: unknown
}) {
  const initialRequestedScale =
    defaultScale == null ? null : clampPdfScale(defaultScale)
  const [uncontrolledScaleState, setUncontrolledScaleState] = React.useState<{
    resetKey: unknown
    requestedScale: number | null
  }>(() => ({
    resetKey,
    requestedScale: initialRequestedScale,
  }))
  const uncontrolledRequestedScale = Object.is(
    uncontrolledScaleState.resetKey,
    resetKey
  )
    ? uncontrolledScaleState.requestedScale
    : initialRequestedScale
  const isControlledScale = controlledScale !== undefined
  const fitWidthScale = getPdfFitWidthScale(containerWidth, pageWidth)
  const resolvedScale = isControlledScale
    ? clampPdfScale(controlledScale)
    : (uncontrolledRequestedScale ?? fitWidthScale)

  const setRequestedScale = React.useCallback(
    (nextScale: number | null) => {
      const normalizedScale =
        nextScale == null ? null : clampPdfScale(nextScale)
      if (isControlledScale) {
        onScaleChange?.(normalizedScale)
        return
      }
      setUncontrolledScaleState((previousState) =>
        Object.is(previousState.resetKey, resetKey) &&
        previousState.requestedScale === normalizedScale
          ? previousState
          : { resetKey, requestedScale: normalizedScale }
      )
    },
    [isControlledScale, onScaleChange, resetKey]
  )

  const zoomIn = React.useCallback(
    () => setRequestedScale(resolvedScale * PDF_ZOOM_STEP),
    [resolvedScale, setRequestedScale]
  )
  const zoomOut = React.useCallback(
    () => setRequestedScale(resolvedScale / PDF_ZOOM_STEP),
    [resolvedScale, setRequestedScale]
  )
  const fitWidth = React.useCallback(
    () => setRequestedScale(null),
    [setRequestedScale]
  )

  return {
    resolvedScale,
    zoomIn,
    zoomOut,
    fitWidth,
  }
}

import * as React from "react"

import {
  findPdfPageByOffset,
  getPdfPageLayout,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout"
import { clamp } from "./pdf-viewer-scale"
import type { PdfPageScrollTarget } from "./pdf-viewer-types"

const PDF_SCROLL_TARGET_HEADROOM = 48

export function usePdfScroll({
  pageCount,
  layout,
  resetKey,
  onVisiblePageChange,
  onScrollProgressChange,
}: {
  pageCount: number
  layout: PdfPageLayoutModel
  resetKey?: unknown
  onVisiblePageChange?: (page: number) => void
  onScrollProgressChange?: (progress: number) => void
}) {
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const lastReportedPageRef = React.useRef(0)
  const scrollFrameRef = React.useRef(0)
  const viewportResetKeyRef = React.useRef<unknown>(resetKey)
  const didMountResetEffectRef = React.useRef(false)
  const [viewportElement, setViewportElementState] =
    React.useState<HTMLDivElement | null>(null)
  const [currentPageState, setCurrentPageState] = React.useState<{
    resetKey: unknown
    page: number
  }>(() => ({ resetKey, page: 1 }))
  const currentPage = Object.is(currentPageState.resetKey, resetKey)
    ? currentPageState.page
    : 1

  const resetViewportForKey = React.useCallback(
    (element: HTMLDivElement, key: unknown) => {
      viewportResetKeyRef.current = key
      element.scrollTop = 0
      element.scrollTo?.({ top: 0, behavior: "auto" })
    },
    []
  )

  const setViewportElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element
      if (element && !Object.is(viewportResetKeyRef.current, resetKey)) {
        resetViewportForKey(element, resetKey)
      }
      setViewportElementState(element)
    },
    [resetKey, resetViewportForKey]
  )

  const measureScroll = React.useCallback(() => {
    scrollFrameRef.current = 0
    const viewportElement = viewportElementRef.current
    if (!viewportElement) return

    const scrollable =
      viewportElement.scrollHeight - viewportElement.clientHeight
    const progress =
      scrollable > 0 ? clamp(viewportElement.scrollTop / scrollable, 0, 1) : 0
    onScrollProgressChange?.(progress)

    const viewportRect = viewportElement.getBoundingClientRect()
    const markerOffset = viewportElement.scrollTop + viewportRect.height * 0.2
    const visiblePage = findPdfPageByOffset(layout, markerOffset)

    if (
      visiblePage >= 1 &&
      visiblePage <= pageCount &&
      visiblePage !== lastReportedPageRef.current
    ) {
      lastReportedPageRef.current = visiblePage
      setCurrentPageState((previousState) =>
        Object.is(previousState.resetKey, resetKey) &&
        previousState.page === visiblePage
          ? previousState
          : { resetKey, page: visiblePage }
      )
      onVisiblePageChange?.(visiblePage)
    }
  }, [layout, onScrollProgressChange, onVisiblePageChange, pageCount, resetKey])
  const measureScrollRef = React.useRef(measureScroll)
  React.useLayoutEffect(() => {
    measureScrollRef.current = measureScroll
  }, [measureScroll])

  const handleScroll = React.useCallback(() => {
    if (scrollFrameRef.current) return
    scrollFrameRef.current = requestAnimationFrame(() =>
      measureScrollRef.current()
    )
  }, [])

  React.useEffect(() => {
    if (!didMountResetEffectRef.current) {
      didMountResetEffectRef.current = true
      return
    }
    lastReportedPageRef.current = 0
    setCurrentPageState((previousState) =>
      Object.is(previousState.resetKey, resetKey) && previousState.page === 1
        ? previousState
        : { resetKey, page: 1 }
    )
    const viewportElement = viewportElementRef.current
    if (viewportElement) {
      resetViewportForKey(viewportElement, resetKey)
    }
  }, [resetKey, resetViewportForKey])

  const scrollToPageTarget = React.useCallback(
    (
      pageNumber: number,
      target: PdfPageScrollTarget,
      options?: ScrollToOptions
    ) => {
      const viewportElement = viewportElementRef.current
      if (!viewportElement || pageNumber < 1 || pageNumber > pageCount) return

      const pageLayout = getPdfPageLayout(layout, pageNumber)
      if (!pageLayout) return

      const requestedTop = Number.isNaN(target.top) ? 0 : target.top
      const targetTopPercent = clamp(requestedTop, 0, 100)
      const targetTop =
        pageLayout.offsetTop +
        (targetTopPercent / 100) * pageLayout.height -
        PDF_SCROLL_TARGET_HEADROOM

      viewportElement.scrollTo({
        top: Math.max(0, targetTop),
        behavior: "smooth",
        ...options,
      })
    },
    [layout, pageCount]
  )
  const getViewportElement = React.useCallback(
    () => viewportElementRef.current,
    []
  )

  React.useEffect(() => {
    if (scrollFrameRef.current) {
      cancelAnimationFrame(scrollFrameRef.current)
      scrollFrameRef.current = 0
    }
  }, [measureScroll])

  React.useEffect(
    () => () => {
      if (scrollFrameRef.current) cancelAnimationFrame(scrollFrameRef.current)
    },
    []
  )

  return {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPageTarget,
    getViewportElement,
  }
}

import type { PdfPageSize } from "./pdf-viewer-types"

export const PDF_PAGE_GAP = 16
export const PDF_PAGE_PADDING = 16

export type PdfPageLayout = {
  pageNumber: number
  width: number
  height: number
  offsetTop: number
}

export type PdfMeasuredPageLayout = {
  pageNumber: number
  width: number
  height: number
  heightDelta: number
}

export type PdfPageLayoutModel = {
  pageCount: number
  totalHeight: number
  maxPageWidth: number
  estimatedWidth: number
  estimatedHeight: number
  measuredPages: readonly PdfMeasuredPageLayout[]
  measuredPageByNumber: ReadonlyMap<number, PdfMeasuredPageLayout>
  prefixHeightDeltas: readonly number[]
}

export function createPdfPageLayout({
  pageCount,
  defaultPageSize,
  pageSizeByNumber,
  scale,
  rotation,
}: {
  pageCount: number
  defaultPageSize: PdfPageSize
  pageSizeByNumber: ReadonlyMap<number, PdfPageSize>
  scale: number
  rotation: number
}): PdfPageLayoutModel {
  const estimatedSize = getRenderedPageSize(defaultPageSize, scale, rotation)
  const measuredPages = Array.from(pageSizeByNumber.entries())
    .filter(([pageNumber]) => pageNumber >= 1 && pageNumber <= pageCount)
    .map(([pageNumber, pageSize]) => {
      const renderedSize = getRenderedPageSize(pageSize, scale, rotation)
      return {
        pageNumber,
        width: renderedSize.width,
        height: renderedSize.height,
        heightDelta: renderedSize.height - estimatedSize.height,
      }
    })
    .filter(
      (page) =>
        page.width !== estimatedSize.width ||
        page.height !== estimatedSize.height
    )
    .sort((a, b) => a.pageNumber - b.pageNumber)

  const measuredPageByNumber = new Map(
    measuredPages.map((page) => [page.pageNumber, page])
  )
  const prefixHeightDeltas: number[] = []
  let totalHeightDelta = 0
  let maxPageWidth = pageCount === 0 ? 0 : estimatedSize.width

  for (const page of measuredPages) {
    totalHeightDelta += page.heightDelta
    prefixHeightDeltas.push(totalHeightDelta)
    maxPageWidth = Math.max(maxPageWidth, page.width)
  }

  return {
    pageCount,
    totalHeight:
      pageCount === 0
        ? 0
        : PDF_PAGE_PADDING * 2 +
          pageCount * estimatedSize.height +
          (pageCount - 1) * PDF_PAGE_GAP +
          totalHeightDelta,
    maxPageWidth,
    estimatedWidth: estimatedSize.width,
    estimatedHeight: estimatedSize.height,
    measuredPages,
    measuredPageByNumber,
    prefixHeightDeltas,
  }
}

export function getPdfPageLayout(
  layout: PdfPageLayoutModel,
  pageNumber: number
): PdfPageLayout | undefined {
  if (pageNumber < 1 || pageNumber > layout.pageCount) return undefined

  const measuredPage = layout.measuredPageByNumber.get(pageNumber)
  return {
    pageNumber,
    width: measuredPage?.width ?? layout.estimatedWidth,
    height: measuredPage?.height ?? layout.estimatedHeight,
    offsetTop: getPdfPageOffsetTop(layout, pageNumber),
  }
}

export function findPdfPageByOffset(
  layout: PdfPageLayoutModel,
  offset: number
) {
  if (layout.pageCount === 0) return 1

  let low = 1
  let high = layout.pageCount
  let match = 1

  while (low <= high) {
    const mid = Math.floor((low + high) / 2)
    if (getPdfPageOffsetTop(layout, mid) <= offset) {
      match = mid
      low = mid + 1
    } else {
      high = mid - 1
    }
  }

  return match
}

export function getPdfVisiblePageNumbers({
  layout,
  scrollTop,
  viewportHeight,
  overscanPages = 2,
}: {
  layout: PdfPageLayoutModel
  scrollTop: number
  viewportHeight: number
  overscanPages?: number
}) {
  if (layout.pageCount === 0) return []

  const startOffset = Math.max(0, scrollTop - viewportHeight)
  const endOffset = scrollTop + viewportHeight * 2
  const firstVisiblePage = findPdfPageByOffset(layout, startOffset)
  const lastVisiblePage = findPdfPageByOffset(layout, endOffset)
  const firstPage = Math.max(1, firstVisiblePage - overscanPages)
  const lastPage = Math.min(layout.pageCount, lastVisiblePage + overscanPages)

  return Array.from(
    { length: lastPage - firstPage + 1 },
    (_, index) => firstPage + index
  )
}

function getRenderedPageSize(
  pageSize: PdfPageSize,
  scale: number,
  rotation: number
) {
  const isRotated = rotation % 180 !== 0
  return {
    width: Math.round((isRotated ? pageSize.height : pageSize.width) * scale),
    height: Math.round((isRotated ? pageSize.width : pageSize.height) * scale),
  }
}

function getPdfPageOffsetTop(layout: PdfPageLayoutModel, pageNumber: number) {
  return (
    PDF_PAGE_PADDING +
    (pageNumber - 1) * (layout.estimatedHeight + PDF_PAGE_GAP) +
    getHeightDeltaBeforePage(layout, pageNumber)
  )
}

function getHeightDeltaBeforePage(
  layout: PdfPageLayoutModel,
  pageNumber: number
) {
  const measuredPageIndex = getLastMeasuredPageIndexBefore(layout, pageNumber)
  return measuredPageIndex < 0
    ? 0
    : layout.prefixHeightDeltas[measuredPageIndex]
}

function getLastMeasuredPageIndexBefore(
  layout: PdfPageLayoutModel,
  pageNumber: number
) {
  let low = 0
  let high = layout.measuredPages.length - 1
  let match = -1

  while (low <= high) {
    const mid = Math.floor((low + high) / 2)
    if (layout.measuredPages[mid].pageNumber < pageNumber) {
      match = mid
      low = mid + 1
    } else {
      high = mid - 1
    }
  }

  return match
}

import * as React from "react"

import {
  getPdfVisiblePageNumbers,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout"

export function usePdfPageVirtualization({
  layout,
  resetKey,
  viewportElement,
}: {
  layout: PdfPageLayoutModel
  resetKey?: unknown
  viewportElement: HTMLDivElement | null
}) {
  const measureFrameRef = React.useRef(0)
  const lastMeasuredResetKeyRef = React.useRef<unknown>(resetKey)
  const getCurrentVisiblePageNumbers = React.useCallback(
    () =>
      getPdfVisiblePageNumbers({
        layout,
        scrollTop: Object.is(lastMeasuredResetKeyRef.current, resetKey)
          ? (viewportElement?.scrollTop ?? 0)
          : 0,
        viewportHeight: viewportElement?.clientHeight ?? 0,
      }),
    [layout, resetKey, viewportElement]
  )
  const [state, setState] = React.useState<{
    layout: PdfPageLayoutModel
    resetKey: unknown
    visiblePageNumbers: readonly number[]
  }>(() => ({
    layout,
    resetKey,
    visiblePageNumbers: getPdfVisiblePageNumbers({
      layout,
      scrollTop: viewportElement?.scrollTop ?? 0,
      viewportHeight: viewportElement?.clientHeight ?? 0,
    }),
  }))
  const visiblePageNumbers =
    Object.is(state.layout, layout) && Object.is(state.resetKey, resetKey)
      ? state.visiblePageNumbers
      : getPdfVisiblePageNumbers({
          layout,
          scrollTop: Object.is(state.resetKey, resetKey)
            ? (viewportElement?.scrollTop ?? 0)
            : 0,
          viewportHeight: viewportElement?.clientHeight ?? 0,
        })

  const measureVisiblePagesNow = React.useCallback(() => {
    measureFrameRef.current = 0
    const nextPageNumbers = getCurrentVisiblePageNumbers()
    lastMeasuredResetKeyRef.current = resetKey
    setState((previousState) =>
      Object.is(previousState.layout, layout) &&
      Object.is(previousState.resetKey, resetKey) &&
      arePageNumbersEqual(previousState.visiblePageNumbers, nextPageNumbers)
        ? previousState
        : { layout, resetKey, visiblePageNumbers: nextPageNumbers }
    )
  }, [getCurrentVisiblePageNumbers, layout, resetKey])
  const measureVisiblePagesNowRef = React.useRef(measureVisiblePagesNow)
  React.useLayoutEffect(() => {
    measureVisiblePagesNowRef.current = measureVisiblePagesNow
  }, [measureVisiblePagesNow])

  const measureVisiblePages = React.useCallback(() => {
    if (measureFrameRef.current) return
    measureFrameRef.current = requestAnimationFrame(() =>
      measureVisiblePagesNowRef.current()
    )
  }, [])

  React.useEffect(() => {
    if (measureFrameRef.current) {
      cancelAnimationFrame(measureFrameRef.current)
      measureFrameRef.current = 0
    }
    measureVisiblePagesNow()
  }, [measureVisiblePagesNow])

  React.useEffect(
    () => () => {
      if (measureFrameRef.current) {
        cancelAnimationFrame(measureFrameRef.current)
      }
    },
    []
  )

  return { visiblePageNumbers, measureVisiblePages }
}

function arePageNumbersEqual(
  previousPageNumbers: readonly number[],
  nextPageNumbers: readonly number[]
) {
  if (previousPageNumbers.length !== nextPageNumbers.length) return false
  return previousPageNumbers.every(
    (pageNumber, index) => pageNumber === nextPageNumbers[index]
  )
}

import * as React from "react"

import type { PdfPageSize } from "./pdf-viewer-types"

export function usePdfPageSizes(resetKey: unknown) {
  const [state, setState] = React.useState<{
    resetKey: unknown
    pageSizeByNumber: ReadonlyMap<number, PdfPageSize>
  }>(() => ({ resetKey, pageSizeByNumber: new Map() }))

  const emptyPageSizeByNumber = React.useMemo<ReadonlyMap<number, PdfPageSize>>(
    () => new Map(),
    [resetKey]
  )
  const pageSizeByNumber = Object.is(state.resetKey, resetKey)
    ? state.pageSizeByNumber
    : emptyPageSizeByNumber

  React.useEffect(() => {
    setState((previousState) =>
      Object.is(previousState.resetKey, resetKey)
        ? previousState
        : { resetKey, pageSizeByNumber: new Map() }
    )
  }, [resetKey])

  const setPageSize = React.useCallback(
    (pageNumber: number, size: PdfPageSize) => {
      setState((previousState) => {
        const previousPageSizeByNumber = Object.is(
          previousState.resetKey,
          resetKey
        )
          ? previousState.pageSizeByNumber
          : emptyPageSizeByNumber
        const current = previousPageSizeByNumber.get(pageNumber)
        if (current?.width === size.width && current.height === size.height) {
          return previousState
        }
        const nextPageSizeByNumber = new Map(previousPageSizeByNumber)
        nextPageSizeByNumber.set(pageNumber, size)
        return { resetKey, pageSizeByNumber: nextPageSizeByNumber }
      })
    },
    [emptyPageSizeByNumber, resetKey]
  )

  return { pageSizeByNumber, setPageSize }
}

import * as React from "react"
import type { PDFDocumentProxy } from "pdfjs-dist"

import { getPdfCanvasPixelSize } from "./pdf-viewer-canvas"
import { readPageResource } from "./pdf-viewer-resource"
import type { PageOverlayProps, PdfPageSize } from "./pdf-viewer-types"

export function PdfPage({
  document,
  pageNumber,
  scale,
  rotation,
  renderOverlay,
  onSize,
}: {
  document: PDFDocumentProxy
  pageNumber: number
  scale: number
  rotation: number
  renderOverlay?: (props: PageOverlayProps) => React.ReactNode
  onSize?: (pageNumber: number, size: PdfPageSize) => void
}) {
  const page = readPageResource(document, pageNumber)
  const intrinsicViewport = React.useMemo(
    () => page.getViewport({ scale: 1, rotation: page.rotate ?? 0 }),
    [page]
  )

  React.useEffect(() => {
    onSize?.(pageNumber, {
      width: intrinsicViewport.width,
      height: intrinsicViewport.height,
    })
  }, [intrinsicViewport.height, intrinsicViewport.width, onSize, pageNumber])

  const viewport = React.useMemo(
    () =>
      page.getViewport({
        scale,
        rotation: ((page.rotate ?? 0) + rotation) % 360,
      }),
    [page, rotation, scale]
  )
  const devicePixelRatio =
    (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return
      const context = canvas.getContext("2d")
      if (!context) return

      canvas.width = getPdfCanvasPixelSize(viewport.width, devicePixelRatio)
      canvas.height = getPdfCanvasPixelSize(viewport.height, devicePixelRatio)
      const renderTask = page.render({
        canvas,
        canvasContext: context,
        viewport,
        transform:
          devicePixelRatio !== 1
            ? [devicePixelRatio, 0, 0, devicePixelRatio, 0, 0]
            : undefined,
      })
      renderTask.promise.catch(() => {
        /* cancelled or failed render */
      })
      return () => renderTask.cancel()
    },
    [devicePixelRatio, page, viewport]
  )

  return (
    <div
      className="relative shadow-sm ring-1 ring-border"
      style={{ width: viewport.width, height: viewport.height }}
      data-slot="pdf-page"
      data-page={pageNumber}
    >
      <canvas
        ref={canvasRef}
        style={{ width: viewport.width, height: viewport.height }}
        className="block bg-white"
      />
      {renderOverlay ? (
        <div className="pointer-events-none absolute inset-0">
          {renderOverlay({
            pageNumber,
            width: viewport.width,
            height: viewport.height,
            scale,
            rotation,
          })}
        </div>
      ) : null}
    </div>
  )
}

import * as React from "react"

import { cn } from "@/lib/utils"

export function PdfViewerRail({
  side,
  open,
  animate,
  children,
}: {
  side: "left" | "right"
  open: boolean
  animate: boolean
  children: React.ReactNode
}) {
  const [width, setWidth] = React.useState<number | null>(null)
  const measureRef = React.useCallback((element: HTMLDivElement | null) => {
    if (!element) return
    setWidth(Math.round(element.offsetWidth))
    if (typeof ResizeObserver === "undefined") return

    const observer = new ResizeObserver(() =>
      setWidth(Math.round(element.offsetWidth))
    )
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  return (
    <div
      data-slot="pdf-viewer-rail"
      data-side={side}
      data-state={open ? "open" : "closed"}
      className={cn(
        "h-full flex-shrink-0 overflow-hidden",
        animate && "transition-[width] duration-200 ease-out"
      )}
      style={animate ? { width: open ? (width ?? undefined) : 0 } : undefined}
    >
      <div ref={measureRef} className="h-full w-max">
        {children}
      </div>
    </div>
  )
}

